540:   const lines = readFileSync(statePath, 'utf8').split(/\r?\n/u).filter((line) => line.trim() !== '');
541:   lines.forEach((line, index) => {
542:     let parsed: unknown;
543:     try {
544:       parsed = JSON.parse(line);
545:     } catch (error: unknown) {
546:       const message = error instanceof Error ? error.message : String(error);
547:       throw new Error(`Pivot state line ${index + 1} is invalid JSON: ${message}`);
548:     }
549:     const event = parsePersistedPivotEvent(parsed, pivotId, index);
550:     const existing = byId.get(event.eventId);
551:     if (existing) {
552:       if (stableJson(eventSemanticPayload(existing)) !== stableJson(eventSemanticPayload(event))) {
553:         throw new Error(`Conflicting durable pivot event "${event.eventId}".`);
554:       }
555:       return;
556:     }
557:     events.push(event);
558:     byId.set(event.eventId, event);
559:   });
