641:   if (typeof value.message !== 'string' || value.message.trim() === '') {
642:     return null;
643:   }
644:   if (value.candidateId !== undefined
645:     && (typeof value.candidateId !== 'string' || !candidateIds.has(value.candidateId))) {
646:     return null;
647:   }
648:   return {
649:     severity: value.severity,
650:     message: value.message.trim(),
651:     ...(typeof value.candidateId === 'string' ? { candidateId: value.candidateId } : {}),
652:   };
653: }
