661:     `# ${String(event.seatId)}`,
662:     '',
663:     `- Status: ${status}`,
664:     `- Parse valid: ${String(event.parseValid === true)}`,
665:     `- Mandate: ${String(event.mandate)}`,
666:     '',
667:     '## Durable Result',
