706: function quorumFromSeatEvents(events: readonly PivotEvent[]): PivotQuorumResult {
707:   const fulfilled = events.filter((event) => event.status === 'fulfilled').length;
708:   const parseValid = events.filter((event) => event.parseValid === true).length;
709:   return {
710:     required: 3,
711:     returned: events.length,
712:     fulfilled,
713:     parseValid,
714:     allFailed: events.length === 3 && fulfilled === 0,
715:     passed: events.length === 3 && fulfilled === 3 && parseValid === 3,
716:   };
717: }
