729: function preflightFailure(
730:   config: NormalizedDivergentConfig,
731:   usage: PivotUsage,
732: ): PivotFailureReason | null {
733:   if (usage.completedPivots >= config.maxPivots) {
734:     return 'max_pivots_exceeded';
735:   }
736:   if (usage.councilSeatOutputs + 3 > config.maxCouncilSeatOutputs) {
737:     return 'max_council_seat_outputs_exceeded';
