789: /** Derive the deterministic pivot id from immutable lineage and normalized trigger data. */
790: export function derivePivotId(input: PivotIdentityInput): string {
791:   const identity = validateIdentity(input);
792:   const digestInput = [
793:     identity.sessionId,
794:     identity.generation,
795:     identity.loopType,
796:     identity.sourceIteration,
797:     identity.normalizedTrigger,
798:   ].join('|');
799:   const digest = createHash('sha256').update(digestInput).digest('hex').slice(0, 12);
800:   return `pivot-${identity.ordinal}-${digest}`;
801: }
