949:   readonly seats: readonly PivotSeatMandate[];
950:   readonly candidates: readonly unknown[];
951:   readonly priorCandidates?: readonly unknown[];
952:   readonly previousFocus: string;
953:   readonly saturatedDirections?: readonly string[];
954:   readonly now?: () => Date | string;
955:   readonly afterEventPersisted?: PivotEventObserver;
