991: interface PersistedPivotConfig {
992:   readonly schemaVersion: 1;
993:   readonly pivotId: string;
994:   readonly identity: PivotIdentityInput;
995:   readonly invariants: { readonly rounds: 1; readonly seats: 3; readonly depth: 1; readonly recursionAllowed: false };
996:   readonly limits: NormalizedDivergentConfig;
997:   readonly usageAtStart: PivotUsage;
998:   readonly seats: readonly PivotSeatMandate[];
999:   readonly acceptedCandidates: readonly PivotCandidate[];
1000:   readonly rejectedCandidates: readonly RejectedPivotCandidateDeduplication[];
1001:   readonly previousFocus: string;
1002:   readonly saturatedDirections: readonly string[];
1003: }
