1005: function parsePersistedIdentity(value: unknown): PivotIdentityInput {
1006:   if (!isRecord(value)) throw new Error('Persisted pivot identity must be an object.');
1007:   const generation = typeof value.generation === 'number'
1008:     ? String(nonNegativeInteger(value.generation, 'identity.generation'))
1009:     : nonEmptyString(value.generation, 'identity.generation');
1010:   return {
1011:     sessionId: nonEmptyString(value.sessionId, 'identity.sessionId'),
1012:     generation,
1013:     loopType: nonEmptyString(value.loopType, 'identity.loopType'),
1014:     sourceIteration: nonNegativeInteger(value.sourceIteration, 'identity.sourceIteration'),
1015:     normalizedTrigger: normalizeTrigger(nonEmptyString(value.normalizedTrigger, 'identity.normalizedTrigger')),
1016:     ordinal: positiveInteger(value.ordinal, 'identity.ordinal'),
1017:   };
1018: }
1019: 
1020: function parsePersistedLimits(value: unknown): NormalizedDivergentConfig {
1021:   if (!isRecord(value)) throw new Error('Persisted pivot limits must be an object.');
1022:   const required = ['maxPivots', 'maxCouncilSeatOutputs', 'minRemainingIterations', 'candidateSimilarityThreshold'];
1023:   if (required.some((key) => !Object.prototype.hasOwnProperty.call(value, key))) {
1024:     throw new Error('Persisted pivot limits are incomplete.');
1025:   }
1026:   return {
1027:     maxPivots: positiveInteger(value.maxPivots, 'limits.maxPivots'),
1028:     maxCouncilSeatOutputs: positiveInteger(value.maxCouncilSeatOutputs, 'limits.maxCouncilSeatOutputs'),
1029:     minRemainingIterations: nonNegativeInteger(value.minRemainingIterations, 'limits.minRemainingIterations'),
1030:     candidateSimilarityThreshold: finiteRatio(value.candidateSimilarityThreshold, 'limits.candidateSimilarityThreshold'),
1031:   };
1032: }
1033: 
1034: function parsePersistedUsage(value: unknown): PivotUsage {
1035:   if (!isRecord(value)) throw new Error('Persisted pivot usage must be an object.');
1036:   return {
1037:     completedPivots: nonNegativeInteger(value.completedPivots, 'usageAtStart.completedPivots'),
1038:     councilSeatOutputs: nonNegativeInteger(value.councilSeatOutputs, 'usageAtStart.councilSeatOutputs'),
1039:     remainingIterations: nonNegativeInteger(value.remainingIterations, 'usageAtStart.remainingIterations'),
1040:     insidePivot: value.insidePivot === true,
1041:   };
1042: }
1043: 
1044: function parsePersistedSeats(value: unknown): readonly PivotSeatMandate[] {
1045:   if (!Array.isArray(value)) throw new Error('Persisted pivot seats must be an array.');
1046:   return normalizeSeats(value.map((seat, index) => {
1047:     if (!isRecord(seat)) throw new Error(`Persisted seat at index ${index} must be an object.`);
1048:     return {
1049:       id: nonEmptyString(seat.id, `seats[${index}].id`),
1050:       mandate: nonEmptyString(seat.mandate, `seats[${index}].mandate`),
1051:     };
1052:   }));
1053: }
1054: 
1055: function parsePersistedCandidates(value: unknown, field: string): readonly PivotCandidate[] {
1056:   if (!Array.isArray(value)) throw new Error(`Persisted ${field} must be an array.`);
1057:   return value.map((candidate, index) => {
1058:     const validation = validatePivotCandidate(candidate);
1059:     if (!validation.valid) {
1060:       throw new Error(`Persisted ${field}[${index}] is not a valid pivot candidate.`);
1061:     }
1062:     return validation.candidate;
1063:   });
1064: }
1065: 
1066: function parsePersistedRejectedCandidates(value: unknown): readonly RejectedPivotCandidateDeduplication[] {
1067:   if (!Array.isArray(value)) throw new Error('Persisted rejectedCandidates must be an array.');
1068:   return value.map((entry, index) => {
1069:     if (!isRecord(entry)
1070:       || entry.accepted !== false
1071:       || typeof entry.maxSimilarity !== 'number'
1072:       || !Number.isFinite(entry.maxSimilarity)
1073:       || entry.maxSimilarity < 0
1074:       || entry.maxSimilarity > 1
1075:       || !Array.isArray(entry.rejections)) {
1076:       throw new Error(`Persisted rejectedCandidates[${index}] is invalid.`);
1077:     }
1078:     const rejections = entry.rejections.map((rejection, rejectionIndex) => {
1079:       if (!isRecord(rejection)
1080:         || typeof rejection.code !== 'string'
1081:         || typeof rejection.message !== 'string'
1082:         || rejection.message.trim() === '') {
1083:         throw new Error(`Persisted rejectedCandidates[${index}].rejections[${rejectionIndex}] is invalid.`);
1084:       }
1085:       const code = rejection.code;
1086:       if (code !== 'invalid_candidate'
1087:         && code !== 'invalid_prior_candidate'
1088:         && code !== 'duplicate_id'
1089:         && code !== 'exact_duplicate'
1090:         && code !== 'materially_similar') {
1091:         throw new Error(`Persisted rejectedCandidates[${index}] has an unknown rejection code.`);
1092:       }
1093:       if (rejection.similarity !== undefined
1094:         && (typeof rejection.similarity !== 'number'
1095:           || !Number.isFinite(rejection.similarity)
1096:           || rejection.similarity < 0
1097:           || rejection.similarity > 1)) {
1098:         throw new Error(`Persisted rejectedCandidates[${index}] has an invalid similarity.`);
1099:       }
1100:       const parsed: RejectedPivotCandidateDeduplication['rejections'][number] = {
1101:         code,
1102:         message: rejection.message.trim(),
1103:         ...(typeof rejection.field === 'string' ? { field: rejection.field } : {}),
1104:         ...(typeof rejection.priorCandidateId === 'string' ? { priorCandidateId: rejection.priorCandidateId } : {}),
1105:         ...(typeof rejection.similarity === 'number' && Number.isFinite(rejection.similarity)
1106:           ? { similarity: rejection.similarity }
1107:           : {}),
1108:       };
1109:       return parsed;
1110:     });
1111:     const candidate = entry.candidate === undefined ? undefined : parsePersistedCandidates([entry.candidate], 'candidate')[0];
1112:     const normalizedFingerprint = entry.normalizedFingerprint;
1113:     if (normalizedFingerprint !== undefined
1114:       && (typeof normalizedFingerprint !== 'string' || normalizedFingerprint.trim() === '')) {
1115:       throw new Error(`Persisted rejectedCandidates[${index}] has an invalid fingerprint.`);
1116:     }
1117:     return {
1118:       accepted: false,
1119:       maxSimilarity: entry.maxSimilarity,
1120:       rejections,
1121:       ...(candidate ? { candidate } : {}),
1122:       ...(typeof normalizedFingerprint === 'string' ? { normalizedFingerprint } : {}),
1123:     };
1124:   });
1125: }
1126: 
1127: function parsePersistedPivotConfig(value: unknown, pivotId: string): PersistedPivotConfig {
1128:   if (!isRecord(value)
1129:     || value.schemaVersion !== 1
1130:     || value.pivotId !== pivotId
1131:     || typeof value.previousFocus !== 'string'
1132:     || !Array.isArray(value.saturatedDirections)) {
1133:     throw new Error(`Pivot config does not match the expected contract for "${pivotId}".`);
1134:   }
1135:   const saturatedDirections = value.saturatedDirections.map((direction, index) => {
1136:     if (typeof direction !== 'string' || direction.trim() === '') {
1137:       throw new Error(`Persisted saturatedDirections[${index}] is invalid.`);
1138:     }
1139:     return direction.trim();
1140:   });
1141:   if (!isRecord(value.invariants)
1142:     || value.invariants.rounds !== 1
1143:     || value.invariants.seats !== 3
1144:     || value.invariants.depth !== 1
1145:     || value.invariants.recursionAllowed !== false) {
1146:     throw new Error('Persisted pivot invariants do not match the one-round contract.');
1147:   }
1148:   return {
1149:     schemaVersion: 1,
1150:     pivotId,
1151:     identity: parsePersistedIdentity(value.identity),
1152:     invariants: { rounds: 1, seats: 3, depth: 1, recursionAllowed: false },
1153:     limits: parsePersistedLimits(value.limits),
1154:     usageAtStart: parsePersistedUsage(value.usageAtStart),
1155:     seats: parsePersistedSeats(value.seats),
1156:     acceptedCandidates: parsePersistedCandidates(value.acceptedCandidates, 'acceptedCandidates'),
1157:     rejectedCandidates: parsePersistedRejectedCandidates(value.rejectedCandidates),
1158:     previousFocus: value.previousFocus.trim(),
1159:     saturatedDirections,
1160:   };
1161: }
1162: 
1163: function readPersistedConfig(configPath: string, pivotId: string): PersistedPivotConfig {
1164:   if (!existsSync(configPath)) {
1165:     throw new Error(`Pivot config not found for "${pivotId}"; run preparePivotTransaction first.`);
1166:   }
1167:   const parsed: unknown = JSON.parse(readFileSync(configPath, 'utf8'));
1168:   try {
1169:     return parsePersistedPivotConfig(parsed, pivotId);
1170:   } catch (error) {
1171:     throw new Error(`Pivot config at "${configPath}" does not match the expected contract: ${error instanceof Error ? error.message : String(error)}`);
1172:   }
1173: }
