1175: /** Validate, dedupe, and persist through "which seats remain to dispatch" — no seat dispatch here. */
1176: export async function preparePivotTransaction(
1177:   options: PreparePivotTransactionOptions,
1178: ): Promise<PivotPrepareResult> {
1179:   if (!isRecord(options)) {
1180:     throw new TypeError('preparePivotTransaction options must be an object.');
1181:   }
1182: 
1183:   const identity = validateIdentity(options.identity);
1184:   const pivotId = derivePivotId(identity);
1185:   const paths = buildPivotCouncilPaths(options.artifactRoot, pivotId);
