413:     || value.occurredAtIso.trim() === ''
414:     || !isLifecycleTransition(value.lifecycle)) {
415:     throw new Error(`Pivot state line ${index + 1} does not match the pivot event contract.`);
416:   }
417:   const event = parsePivotEventName(value.event);
418:   if (event === null || (event === 'pivot_failed'
419:     && (typeof value.reason !== 'string' || !PIVOT_FAILURE_REASONS.has(value.reason)))) {
420:     throw new Error(`Pivot state line ${index + 1} does not match the pivot event contract.`);
421:   }
422:   const parsed: PivotEvent = {
423:     ...value,
424:     schemaVersion: 1,
425:     eventId: value.eventId.trim(),
426:     event,
427:     pivotId,
428:     occurredAtIso: value.occurredAtIso.trim(),
429:     lifecycle: value.lifecycle,
430:   };
431:   return parsed;
432: }
