803: /** Build and validate the isolated artifact paths for one pivot Council transaction. */
804: export function buildPivotCouncilPaths(artifactRoot: string, pivotId: string): PivotCouncilPaths {
805:   const rootInput = nonEmptyString(artifactRoot, 'artifactRoot');
806:   if (!/^pivot-[1-9][0-9]*-[a-f0-9]{12}$/u.test(pivotId)) {
807:     throw new TypeError('pivotId must match pivot-<ordinal>-<12 lowercase hex characters>.');
808:   }
809:   const canonicalRoot = resolveProspectiveRealPath(rootInput);
810:   if (pathContainsAiCouncil(canonicalRoot)) {
811:     throw new TypeError('artifactRoot must not be inside an ai-council artifact tree.');
812:   }
813:   const pivotRoot = join(canonicalRoot, 'divergent', 'pivots', pivotId);
814:   const councilRoot = join(pivotRoot, 'council');
815:   const seatsRoot = join(councilRoot, 'seats');
816:   return {
817:     artifactRoot: canonicalRoot,
818:     pivotRoot,
819:     councilRoot,
820:     configPath: join(councilRoot, 'config.json'),
821:     statePath: join(councilRoot, 'state.jsonl'),
822:     seatsRoot,
823:     seatPaths: [
824:       join(seatsRoot, 'seat-001.md'),
825:       join(seatsRoot, 'seat-002.md'),
826:       join(seatsRoot, 'seat-003.md'),
827:     ],
828:     deliberationPath: join(councilRoot, 'deliberation.md'),
829:     reportPath: join(councilRoot, 'report.md'),
830:   };
831: }
