833: /** Parse and validate an injected seat output without accepting partial reports. */
834: export function parsePivotSeatReport(
835:   output: unknown,
836:   expectedSeatId: string,
837:   candidateIds: ReadonlySet<string>,
838: ): PivotSeatReportParseResult {
839:   let parsed = output;
840:   if (typeof parsed === 'string') {
841:     try {
842:       parsed = JSON.parse(parsed);
843:     } catch {
844:       return { valid: false, reason: 'Seat output must be a JSON object or JSON object string.' };
845:     }
846:   }
847:   if (!isRecord(parsed)) {
848:     return { valid: false, reason: 'Seat output must be an object.' };
849:   }
850:   if (parsed.seatId !== expectedSeatId) {
851:     return { valid: false, reason: `Seat report must identify itself as "${expectedSeatId}".` };
852:   }
853:   const selectedCandidateId = parsed.selectedCandidateId;
854:   if (selectedCandidateId !== null
855:     && (typeof selectedCandidateId !== 'string' || !candidateIds.has(selectedCandidateId))) {
856:     return { valid: false, reason: 'selectedCandidateId must be null or identify a valid candidate.' };
857:   }
858:   if (typeof parsed.materialEndorsement !== 'boolean') {
859:     return { valid: false, reason: 'materialEndorsement must be a boolean.' };
860:   }
861:   if (parsed.materialEndorsement && selectedCandidateId === null) {
862:     return { valid: false, reason: 'A material endorsement must identify a selected candidate.' };
863:   }
864:   if (typeof parsed.rationale !== 'string' || parsed.rationale.trim() === '') {
865:     return { valid: false, reason: 'Seat rationale must be a non-empty string.' };
866:   }
867:   if (!Array.isArray(parsed.blockers)) {
868:     return { valid: false, reason: 'Seat blockers must be an array.' };
869:   }
870:   const blockers = parsed.blockers.map((blocker) => parseBlocker(blocker, candidateIds));
871:   if (blockers.some((blocker) => blocker === null)) {
872:     return { valid: false, reason: 'Every seat blocker must match the blocker contract.' };
873:   }
874:   return {
875:     valid: true,
876:     report: {
877:       seatId: expectedSeatId,
878:       selectedCandidateId: selectedCandidateId as string | null,
879:       materialEndorsement: parsed.materialEndorsement,
880:       rationale: parsed.rationale.trim(),
881:       blockers: blockers as PivotSeatBlocker[],
882:     },
883:   };
884: }
