886: /** Evaluate two-of-three material endorsement and the global high-blocker veto. */
887: export function evaluatePivotAgreement(
888:   reports: readonly PivotSeatReport[],
889:   candidateOrder: readonly string[],
890: ): PivotAgreementResult {
891:   const highSeverityBlockers = reports.flatMap((report) =>
892:     report.blockers.filter((blocker) => blocker.severity === 'high'));
893:   const tallies = candidateOrder.map((candidateId) => {
894:     const endorsingSeatIds = reports
895:       .filter((report) => report.materialEndorsement && report.selectedCandidateId === candidateId)
896:       .map((report) => report.seatId);
897:     return { candidateId, endorsementCount: endorsingSeatIds.length, endorsingSeatIds };
898:   });
899:   const selected = tallies.find((tally) => tally.endorsementCount >= 2) ?? null;
900:   const converged = reports.length === 3 && selected !== null && highSeverityBlockers.length === 0;
901:   return {
902:     converged,
903:     selectedCandidateId: selected?.candidateId ?? null,
904:     endorsementCount: selected?.endorsementCount ?? 0,
905:     endorsingSeatIds: selected?.endorsingSeatIds ?? [],
906:     tallies,
907:     highSeverityBlockers,
908:     reason: highSeverityBlockers.length > 0
909:       ? 'high_severity_blocker'
910:       : selected === null
911:         ? 'insufficient_endorsement'
912:         : 'agreed',
913:   };
914: }
