function persistConfig(path: string, config: Record<string, unknown>): void {
  if (existsSync(path)) {
    const existing = JSON.parse(readFileSync(path, 'utf8')) as unknown;
    if (!isRecord(existing)) {
      throw new Error('Existing pivot config conflicts with the resumed transaction.');
    }
    // usageAtStart records the budget when the attempt opened; a resume reports the
    // attempt's own progress, which legitimately differs from the opening counts.
    const { usageAtStart: _persistedUsage, ...persistedInputs } = existing;
    const { usageAtStart: _nextUsage, ...nextInputs } = config;
    if (stableJson(persistedInputs) !== stableJson(nextInputs)) {
      throw new Error('Existing pivot config conflicts with the resumed transaction.');
    }
    return;
  }
  writeStateIfChangedAtomic(path, config, new Map<string, string>());
}

